    "q": "Theo Hồ Chí Minh, “không tham địa vị, không tham tiền tài, không tham sung sướng, không ham người tâng bốc mình; vì vậy mà quang minh chính đại, không bao giờ hủ hóa” là nội dung của khái niệm nào?",
